const HISTORY = [
  {id:'1950',year:1950,title:'The first Formula 1 World Championship',summary:'The first official World Championship season begins with seven championship rounds and the Drivers’ title awarded to Nino Farina.',regulations:['The FIA Formula 1 World Championship is established.','Championship scoring and seven qualifying rounds form the original sporting framework.','Cars use a wide range of front- and rear-engined concepts under the original Formula 1 technical formula.'],beginner:'This is the starting point of the modern F1 championship.'},
  {id:'1952',year:1952,title:'Formula 2-based cars',summary:'The World Championship temporarily runs to Formula 2 technical regulations because of a shortage of suitable Formula 1 machinery.',regulations:['F2 regulations are used for the World Championship.','Engine capacity and naturally aspirated layouts are restricted under the smaller formula.'],beginner:'F1 rules changed because the championship needed enough eligible cars to form a viable grid.'},
  {id:'1958',year:1958,title:'Constructors’ Championship arrives',summary:'The second World Championship is introduced for constructors, adding a team-level title alongside the Drivers’ Championship.',regulations:['Constructors’ Championship introduced.','Fuel strategy and race distances continue to be governed by the contemporary sporting rules.'],beginner:'From this season, teams have their own championship to fight for.'},
  {id:'1961',year:1961,title:'Smaller engines and new safety emphasis',summary:'The championship adopts a 1.5-litre naturally aspirated engine formula and speed-control measures.',regulations:['Maximum engine capacity reduced to 1.5 litres for naturally aspirated engines.','Minimum car weight requirements change with the new formula.','The reduced engine formula reshapes the balance between power and chassis efficiency.'],beginner:'F1 deliberately reduces engine size to control performance and cost.'},
  {id:'1966',year:1966,title:'Three-litre engines return',summary:'Engine capacity is increased to three litres for naturally aspirated engines, opening a new power era.',regulations:['Naturally aspirated engines can run up to 3.0 litres.','2.0-litre supercharged engines are also permitted under the formula.'],beginner:'The bigger engines make power a much larger part of the competitive equation.'},
  {id:'1968',year:1968,title:'Aerodynamics becomes a weapon',summary:'Wings and aerodynamic devices rapidly become central to car performance.',regulations:['Moveable aerodynamic wings become widespread.','Wing mounting and safety requirements evolve as teams search for downforce.'],beginner:'Teams discover that controlling airflow can make a car faster without simply adding engine power.'},
  {id:'1970',year:1970,title:'Ground-effect ideas begin to emerge',summary:'Aerodynamic development moves toward managing airflow under and around the car.',regulations:['Teams increasingly explore underbody airflow and aerodynamic load generation.','Safety requirements continue to evolve around aerodynamic devices.'],beginner:'The ideas developed here eventually lead to the famous ground-effect era.'},
  {id:'1978',year:1978,title:'Ground effect becomes dominant',summary:'Lotus demonstrates how shaped sidepods and underbody tunnels can generate large amounts of efficient downforce.',regulations:['Underbody ground-effect aerodynamics become a major performance tool.','Sliding skirts are developed to seal the floor against the track.'],beginner:'Air under the car becomes almost as important as the wings on top of it.'},
  {id:'1983',year:1983,title:'Ground effect banned',summary:'Full ground-effect cars are prohibited as the rules move toward safer, more predictable aerodynamic behaviour.',regulations:['Sliding skirts are banned.','A flat-bottom requirement limits the ability to generate extreme underbody suction.'],beginner:'The FIA removes the most extreme ground-effect solutions to improve safety.'},
  {id:'1988',year:1988,title:'Turbo era reaches its final season',summary:'Turbocharged engines compete for the last time before naturally aspirated power becomes mandatory.',regulations:['Turbo engines face restrictive boost and fuel-flow rules before their 1989 ban.','Naturally aspirated alternatives remain available.'],beginner:'The sport prepares to end the turbo era after a period of extraordinary engine power.'},
  {id:'1989',year:1989,title:'Naturally aspirated engines only',summary:'Turbocharged engines are banned and the championship returns to naturally aspirated power.',regulations:['Turbocharged engines banned.','Naturally aspirated engines become the sole engine architecture.'],beginner:'This closes the first turbo era and begins a long naturally aspirated period.'},
  {id:'1994',year:1994,title:'Electronic driver aids restricted',summary:'Major electronic aids are removed as F1 responds to concerns about driver assistance and racing control.',regulations:['Active suspension, traction control and launch-control systems are prohibited at the start of the season.','Safety regulations are strengthened following the tragic 1994 Imola weekend.'],beginner:'The driver is given more direct responsibility for controlling the car.'},
  {id:'1998',year:1998,title:'Grooved tyres and narrower cars',summary:'Tyres and chassis dimensions change dramatically to reduce cornering speed.',regulations:['Grooved dry-weather tyres introduced.','Cars become narrower.','Aerodynamic rules are revised to reduce cornering performance.'],beginner:'The visible grooves in tyres are part of an attempt to reduce mechanical grip.'},
  {id:'2003',year:2003,title:'Qualifying and points system changes',summary:'Sporting regulations are adjusted to make the weekend more competitive and the championship more balanced.',regulations:['Qualifying format is changed to a single timed lap for each driver.','Points are awarded to the top eight rather than the previous top six.'],beginner:'F1 changes the weekend format and spreads points to more finishers.'},
  {id:'2009',year:2009,title:'Kinetic energy recovery and aero reset',summary:'The sport introduces KERS as a major new energy-recovery technology and dramatically simplifies aerodynamics.',regulations:['Kinetic Energy Recovery Systems (KERS) are introduced.','Front and rear wings are redesigned.','Diffusers and aerodynamic surfaces are heavily restricted.','Slick tyres return after the grooved-tyre era.'],beginner:'The car is redesigned to reduce aero complexity while recovering braking energy.'},
  {id:'2011',year:2011,title:'DRS introduced',summary:'The Drag Reduction System becomes a controlled overtaking aid.',regulations:['Adjustable rear-wing DRS introduced.','DRS use is restricted to designated activation zones during races.','KERS continues as an energy deployment system.'],beginner:'Drivers can open a rear-wing flap in a designated zone to reduce drag and improve overtaking chances.'},
  {id:'2014',year:2014,title:'Turbo-hybrid power units',summary:'F1 moves from naturally aspirated V8s to 1.6-litre V6 turbo-hybrid power units.',regulations:['1.6-litre V6 turbo hybrid power units introduced.','MGU-K recovers kinetic energy under braking.','MGU-H recovers exhaust heat energy.','Fuel-flow limits and fuel-efficiency requirements become central to performance.'],beginner:'The engine becomes a hybrid energy system rather than a conventional high-revving V8.'},
  {id:'2017',year:2017,title:'Wider, faster cars',summary:'Technical rules increase tyre width and aerodynamic load to make cars significantly faster.',regulations:['Wider front and rear tyres introduced.','Cars become wider with larger aerodynamic surfaces.','Downforce targets increase significantly.'],beginner:'F1 cars become visibly wider and faster through corners.'},
  {id:'2019',year:2019,title:'Front-wing and race-management changes',summary:'Aerodynamic rules are adjusted to make cars easier to follow and the fastest-lap point is introduced.',regulations:['Simplified front wings aim to reduce wake sensitivity.','Rear-wing and brake-duct rules are revised.','A championship point is awarded for the fastest lap when the driver finishes in the top 10.'],beginner:'The rules try to make following another car less difficult.'},
  {id:'2021',year:2021,title:'Cost cap and aero reduction',summary:'F1 introduces its first team spending cap while reducing floor and diffuser performance ahead of the 2022 reset.',regulations:['A team cost cap is introduced at a $145 million baseline.','Floor edges are cut back to reduce downforce.','Diffuser fences are shortened.','A new sliding-scale aerodynamic testing allowance is introduced.'],beginner:'Money becomes regulated as well as the cars, with lower-spending teams given a better chance to compete.'},
  {id:'2022',year:2022,title:'Ground effect returns',summary:'A major technical reset brings shaped underfloor tunnels, 18-inch wheels and a new approach to closer racing.',regulations:['Ground-effect underfloor tunnels become the main aerodynamic concept.','18-inch wheels and low-profile tyres replace 13-inch wheels.','Bargeboards are removed.','Cars are designed to produce less disruptive wake.','The power unit is frozen while teams prepare for the 2026 engine generation.'],beginner:'The floor becomes the main aerodynamic device, helping cars follow each other more closely.'},
  {id:'2026',year:2026,title:'Active aerodynamics and a new power-unit era',summary:'The biggest modern rules reset combines a lighter car, active aero and a much larger electrical contribution.',regulations:['Active front and rear aerodynamics replace the old DRS concept.','Power units target roughly a 50/50 thermal-electric power split.','MGU-H is removed and MGU-K output rises to 350 kW.','Advanced sustainable fuel becomes mandatory.','Cars are designed around a lighter, more agile concept.','New energy-management tools such as Boost and Recharge become part of race strategy.'],beginner:'The driver now manages a much larger electrical-energy strategy while the wings actively change between low-drag and high-downforce modes.'}
]

const EXTRA_GLOSSARY = [
  ['D','DRS','Drag Reduction System — the previous-generation adjustable rear-wing system used in designated zones to reduce drag and assist overtaking.'],
  ['D','Delta','A target time or speed reference that a driver must stay within during controlled-speed periods such as the Virtual Safety Car.'],
  ['E','ERS','Energy Recovery System — the hybrid system that recovers energy and stores it for later deployment.'],
  ['M','MGU-K','Motor Generator Unit-Kinetic. It recovers energy and deploys electrical power to the rear wheels; in 2026 its maximum output rises substantially.'],
  ['M','MGU-H','Motor Generator Unit-Heat. The exhaust-energy recovery unit used in the 2014–2025 hybrid era and removed for 2026.'],
  ['A','Active aerodynamics','2026 aerodynamic system that changes wing configuration to balance cornering load and straight-line efficiency.'],
  ['B','Boost','A 2026 energy-deployment concept that gives a driver extra electrical performance for attacking or defending.'],
  ['R','Recharge','A 2026 energy-management mode in which the driver and team prioritise recovering electrical energy.'],
  ['M','Manual Override Mode','A 2026 overtaking aid that gives a following car additional electrical deployment when conditions are met.'],
  ['P','Porpoising','A vertical bouncing effect caused by aerodynamic flow instability, particularly associated with ground-effect floors.'],
  ['F','Formation lap','The lap completed before the race start while drivers take their grid positions and prepare the car and tyres.'],
  ['P','Parc fermé','The controlled period during which teams are restricted from making changes to the car except those permitted by the regulations.'],
  ['S','Sprint','A shorter race held at selected Grands Prix that awards championship points and changes the weekend format.'],
  ['V','VSC','Virtual Safety Car — a digital speed-control procedure that neutralises a race without physically bunching the field behind a safety car.'],
  ['U','Underfloor','The underside of the car, including tunnels and diffuser surfaces that generate aerodynamic load.'],
  ['D','Downwash','The downward deflection of airflow produced by aerodynamic surfaces.'],
  ['C','Chicane','A sequence of alternating corners designed to slow cars and change the racing line.'],
  ['S','Slipstream','The lower-drag region behind another car that can help a following car gain speed on a straight.'],
  ['T','Tow','The aerodynamic benefit of following a car closely, especially during qualifying.'],
  ['P','Pit limiter','A system that restricts the car to the pit-lane speed limit.'],
  ['A','Allocation','The number of tyre sets or regulated power-unit or gearbox components available to a car under the sporting rules.'],
  ['A','Appeal','A formal request to review an FIA decision or sporting ruling where the regulations allow it.'],
  ['B','Brake balance','The distribution of braking force between the front and rear brakes, which the driver can adjust to change car behaviour.'],
  ['B','Brake-by-wire','An electronic braking system that works with the rear axle and energy recovery to manage braking force.'],
  ['B','Black and orange flag','A warning requiring a driver to pit because the car has damage or a mechanical problem that could be dangerous.'],
  ['C','CFD','Computational Fluid Dynamics: computer simulation used by teams to study airflow around the car.'],
  ['C','Chassis','The main structural part of the car that supports the driver, suspension and other major components.'],
  ['D','Differential','The drivetrain component that allows the driven wheels to rotate at different speeds while cornering.'],
  ['D','Diffuser','The rear section of the floor that helps manage airflow leaving beneath the car and contributes to downforce.'],
  ['D','DNQ','Did Not Qualify — a classification used when a driver does not qualify for the race under the applicable rules.'],
  ['D','DSQ','Disqualified — a driver or car has been excluded from the relevant session or classification.'],
  ['E','Esses','A sequence of left-right or right-left corners that forms an S-shaped section of track.'],
  ['K','Kerb','The raised or painted edge at the side of a circuit. Drivers may use kerbs to shorten or open a corner, but excessive use can hurt the car.'],
  ['L','Lift and coast','A fuel and energy-saving driving technique where the driver lifts off the throttle before the normal braking point and coasts into the corner.'],
  ['L','Lock-up','When a wheel stops rotating under braking and slides over the track surface, often creating a flat spot.'],
  ['M','Marbles','Small pieces of rubber shed from tyres that collect away from the main racing line and can reduce grip when driven over.'],
  ['O','Oversteer','When the rear of the car loses grip and the car turns more than the driver intended.'],
  ['O','Overtake Mode','A 2026 energy-deployment aid that replaces DRS and can provide extra electrical performance to help a following car attack.'],
  ['P','Package','A group of car upgrades designed to work together as one aerodynamic or mechanical development package.'],
  ['P','Pit board','A board shown from the pit wall to give the driver information such as position, gaps, lap count or pit instructions.'],
  ['P','Pit lane','The controlled lane alongside the circuit containing team garages and pit boxes, with a mandatory speed limit.'],
  ['P','Pit stop','A stop in the pit box, normally for tyre changes and sometimes repairs or adjustments.'],
  ['P','Pit wall','The team area beside the pit lane where strategists, engineers and senior personnel monitor the session and communicate with the driver.'],
  ['R','Race pace','The representative lap speed a driver can maintain over several laps rather than on a single qualifying-style lap.'],
  ['R','Racing line','The path through a corner that generally allows a driver to carry the best combination of entry speed, apex speed and exit speed.'],
  ['T','Track evolution','The way grip and lap times change as more rubber is laid down and track conditions change during a weekend.'],
  ['T','Tyre blanket','A heating system used before a session to bring tyres closer to their intended operating range.'],
  ['U','Unsafe release','A car being released from its pit position in a way that creates a dangerous situation for another car or person.'],
  ['U','Upgrade','A newly developed car component intended to improve performance, efficiency, reliability or aerodynamic behaviour.'],
  ['V','Visor','The transparent part of the driver’s helmet that protects the eyes while allowing the driver to see.'],
  ['Z','Zylon','A strong protective material used in parts of F1 driver and car safety equipment.'],
].map(([letter,term,definition])=>({letter,term,definition}))

seedDatabase({ archive, worldChampions: WORLD_CHAMPIONS, constructorChampions: CONSTRUCTOR_CHAMPIONS, history: HISTORY, extraGlossary: EXTRA_GLOSSARY })
for (const row of EXTRA_GLOSSARY) putContent('glossary',`${row.letter}-${row.term}`,row)


// Educational content enrichment. These fields live in SQLite too, so the Admin editor can change them.
const EDUCATIONAL = {
  flags: {
    green:{explanation:'The green flag means the track is clear and normal racing conditions have resumed.',whatToDo:'Drivers can race normally, subject to the other sporting instructions in force at that location.',why:'It tells drivers that the hazard or local restriction signalled previously has ended.',example:'After a yellow-flag zone is cleared, a green flag may be shown so drivers know they can return to normal racing speed.',watchFor:'Watch how the cars accelerate again and how the marshals change from a hazard signal back to a clear-track signal.'},
    yellow:{explanation:'A yellow flag warns that there is a hazard on or near the track. The driver must immediately reduce speed and be prepared to change direction or stop.',whatToDo:'Slow down, do not overtake where the yellow applies, and be ready for a stopped car, debris or marshals working near the circuit.',why:'Marshals need a fast visual way to warn drivers about danger before the driver reaches it.',example:'If a car stops at the outside of a corner, the next drivers may see yellow flags before reaching the incident.',watchFor:'Look for reduced speed and changes in driving behaviour through the affected sector.'},
    'double-yellow':{explanation:'Double yellow flags indicate a serious hazard. Drivers must significantly reduce speed and be prepared to stop.',whatToDo:'Reduce speed substantially, do not overtake and be ready to stop if required.',why:'The hazard is severe enough that simply lifting off is not considered sufficient protection.',example:'A recovery vehicle or badly positioned car may lead race control to use double yellows in the affected zone.',watchFor:'Cars should be visibly slower and more cautious through the zone.'},
    red:{explanation:'A red flag stops the session or race. The field must follow race-control instructions and return to the appropriate controlled area.',whatToDo:'Stop competitive running, slow safely and follow the prescribed procedure for returning to the pits or grid.',why:'Conditions may be unsafe, or race control may need to stop the session to recover a car, clear debris or address a serious incident.',example:'Heavy weather or a major accident can cause race control to suspend a session with a red flag.',watchFor:'Timing may be suspended or reset according to the applicable procedure, and the field will be managed by race control.'},
    blue:{explanation:'The blue flag is used to manage faster traffic. A lapped driver may be instructed to let a faster car through.',whatToDo:'Follow the sporting instruction and avoid unnecessarily delaying the faster car.',why:'It helps separate cars racing for position from cars that are a lap or more behind.',example:'If a leader catches a backmarker, blue flags can warn the slower car that the leader is approaching.',watchFor:'The faster car normally gains time without the lapped car fighting for track position.'},
    black:{explanation:'The black flag is a serious sporting instruction directed at a particular driver. The driver is required to return to the pits and is excluded from the relevant session or race.',whatToDo:'Return to the pits as instructed and comply with race-control procedures.',why:'It is used when race control or the stewards impose a severe sporting sanction.',example:'A driver receiving a black flag cannot simply continue racing and decide to serve it later.',watchFor:'The driver’s car number accompanies the signal so the instruction is clearly directed to that competitor.'},
    'black-white':{explanation:'The black-and-white flag is a formal warning to a driver for unsporting behaviour or a sporting infringement.',whatToDo:'Treat it as a final warning to change the behaviour and avoid another infringement.',why:'It gives race control a visible way to warn a driver before a more serious sporting penalty may follow.',example:'Repeatedly abusing track limits or another form of unsporting behaviour can lead to a black-and-white warning.',watchFor:'The driver number is normally shown with the flag so the warning is specific to that competitor.'},
    chequered:{explanation:'The chequered flag confirms that the competitive session or race has finished.',whatToDo:'Complete the lap safely and follow the post-session or parc fermé instructions.',why:'It provides the final visual signal that the competitive running is over.',example:'At the end of the Grand Prix, the first car to receive the chequered flag has completed the race distance and classification is then processed.',watchFor:'Cars slow after completing the finish procedure and teams switch from live racing decisions to post-race procedures.'}
  },
  sessions: {
    FP1:{explanation:'Free Practice 1 is the first opportunity for teams to run the car on the circuit during a normal weekend.',whatHappens:'Engineers check the baseline setup, gather aerodynamic and tyre data, test components and allow the driver to learn the track conditions.',watchFor:'Watch which tyres are used, how much fuel the teams appear to be carrying, and whether drivers make repeated runs rather than one headline lap.',whyItMatters:'The data becomes a reference for setup decisions in later sessions.',example:'A team may compare two front-wing or suspension settings to understand which gives the driver a better balance.'},
    FP2:{explanation:'Free Practice 2 is often especially valuable for long-run and race preparation because teams can study tyre behaviour over several laps.',whatHappens:'Teams combine performance runs with longer race simulations and compare tyre degradation, fuel behaviour and balance.',watchFor:'Long sequences of similar lap times are more useful for judging race pace than one qualifying-style lap.',whyItMatters:'It helps the team decide which tyre and race strategy combinations are realistic.',example:'A driver may complete ten or more laps on one compound so engineers can estimate how quickly performance falls away.'},
    FP3:{explanation:'Free Practice 3 is the final practice session and the last major chance to refine the car before qualifying.',whatHappens:'Teams focus on final setup changes, qualifying preparation and confirming that overnight adjustments have worked.',watchFor:'Look for short runs on the softer qualifying compounds and teams practising their final preparation.',whyItMatters:'Small setup decisions can affect both qualifying position and the starting point for race strategy.',example:'A team may use FP3 to decide whether it needs more front grip or a lower-drag setup.'},
    Q1:{explanation:'Q1 is the first part of qualifying. Every driver attempts to set a representative lap before the first elimination.',whatHappens:'Drivers run for lap time while teams manage traffic, tyre preparation and track evolution. The slowest group is eliminated under the qualifying format.',watchFor:'The track usually becomes faster as more rubber is laid down, so the order can change late in the session.',whyItMatters:'A poor Q1 result can put a driver at the back of the field before the race even starts.',example:'A driver who waits too long may be caught by traffic or a red flag and fail to improve.'},
    Q2:{explanation:'Q2 is the second qualifying segment for the drivers who survive Q1.',whatHappens:'Teams refine tyre preparation and timing while chasing the lap needed to reach the final segment.',watchFor:'Drivers may use different tyre choices depending on the weekend format and strategy rules.',whyItMatters:'Q2 determines which drivers get to fight for the front of the grid in Q3.',example:'A driver can gain several places simply by finding a clean final run as the track improves.'},
    Q3:{explanation:'Q3 is the final qualifying segment and the main fight for pole position.',whatHappens:'The remaining drivers make their fastest attempts, usually with maximum preparation and minimal fuel.',watchFor:'Compare the final sector splits and the gaps between teammates because tiny differences can decide pole.',whyItMatters:'The starting position strongly influences the first-lap and race strategy options.',example:'Two drivers can be separated by only a few hundredths of a second even though both have produced excellent laps.'},
    SPRINT:{explanation:'The Sprint is a shorter competitive race used at selected Grand Prix weekends and follows a different weekend schedule from a standard event.',whatHappens:'Drivers race over a shorter distance while managing tyres, overtaking opportunities and championship points.',watchFor:'Because the race is shorter, teams may accept more aggressive tyre and energy decisions.',whyItMatters:'It awards championship points and can affect the way teams approach the rest of the weekend.',example:'A driver may attack more aggressively because there are fewer laps in which to recover lost positions.'},
    RACE:{explanation:'The Grand Prix is the main championship race and the session in which the bulk of the race weekend’s championship points are normally scored.',whatHappens:'Drivers manage pace, tyres, fuel and energy while teams make pit-stop and safety-car decisions.',watchFor:'Follow the tyre ages, pit windows, gaps, safety-car periods and the difference between qualifying pace and long-run pace.',whyItMatters:'The race determines the official finishing order and contributes to both championships.',example:'A driver can start behind a rival but finish ahead through better tyre management and a well-timed pit stop.'}
  },
  rules: {
    Championship:{explanation:'Formula 1 has two main championship classifications: the Drivers’ Championship and the Constructors’ Championship.',howItWorks:'Drivers score points from eligible race and sprint results. Constructor points are the points scored by the team’s eligible drivers, subject to the regulations and classification.',example:'Two teammates can both score points for the same constructor even while fighting each other for the Drivers’ Championship.',whyItMatters:'It explains why one driver can win the Drivers’ title while a different team wins the Constructors’ title.',beginnerTip:'Think of the Drivers’ Championship as the individual competition and the Constructors’ Championship as the team competition.'},
    Grid:{explanation:'The starting grid is the ordered list of cars at the beginning of a race or Sprint.',howItWorks:'Qualifying establishes the starting order, but penalties, non-participation and official decisions can change a driver’s final grid position.',example:'A driver who qualifies third but receives a grid penalty may start lower than third.',whyItMatters:'Starting position changes the amount of clean air, traffic and overtaking a driver is likely to face.',beginnerTip:'Qualifying position and actual starting position are not always the same.'},
    'Pit Lane':{explanation:'The pit lane is a controlled section where cars enter for pit stops and access to team garages.',howItWorks:'Cars must respect the pit-lane speed limit and obey entry, exit and race-control procedures.',example:'A driver speeding in the pit lane can receive a penalty even if they gain no track position.',whyItMatters:'The pit lane is a high-risk working area with mechanics, equipment and cars moving in a confined space.',beginnerTip:'A pit stop is not simply stopping; the driver must enter and exit the pit lane correctly.'},
    Tyres:{explanation:'Tyre regulations define which compounds and tyre sets drivers can use and how teams may manage them during a weekend.',howItWorks:'Teams choose from the compounds allocated for the event and plan when each set will be used.',example:'A team may save a new soft set for qualifying rather than using it early in practice.',whyItMatters:'Tyres often determine whether a car can maintain pace for a long stint.',beginnerTip:'Think about tyres as a performance resource: grip now versus life later.'},
    'Safety Car':{explanation:'The Safety Car is a physical car that leads the field when the race cannot continue at normal speed but a complete stop is not necessary.',howItWorks:'Cars form a controlled queue behind the Safety Car while race control manages the incident and the track.',example:'A crash may trigger a Safety Car period so marshals can work without cars racing past at full speed.',whyItMatters:'A Safety Car can dramatically change gaps and make pit stops strategically cheaper.',beginnerTip:'Watch how the field bunches together — that is why a Safety Car can erase a large lead.'},
    'Virtual Safety Car':{explanation:'The Virtual Safety Car controls car speeds without using a physical Safety Car to bunch the field together.',howItWorks:'Drivers must stay within a prescribed speed-time delta while continuing around the circuit.',example:'A stranded car can trigger VSC while marshals recover it, reducing the speed of every driver through the affected period.',whyItMatters:'It improves safety while preserving more of the existing gaps than a physical Safety Car.',beginnerTip:'VSC means controlled speed; Safety Car means controlled speed plus a physical car leading the field.'},
    Penalties:{explanation:'Penalties are sporting sanctions applied when drivers or teams breach the regulations.',howItWorks:'Stewards investigate incidents using timing, video, radio and other evidence before deciding the appropriate sanction.',example:'Depending on the infringement, a driver could receive a time penalty or a grid penalty.',whyItMatters:'Penalties ensure that gaining an advantage by breaking the rules is not treated as normal racing.',beginnerTip:'An investigation does not automatically mean a penalty; the stewards must establish whether a breach occurred.'},
    'Track Limits':{explanation:'Track limits define where the racing surface ends. Drivers cannot repeatedly or deliberately gain an advantage by exceeding them.',howItWorks:'Timing systems, cameras and other evidence can be used to detect infringements. Consequences depend on the applicable sporting rules.',example:'A lap can be deleted in qualifying if a driver exceeds the track limits at a monitored corner.',whyItMatters:'Track limits stop drivers from using extra asphalt or run-off as a free shortcut.',beginnerTip:'A fast lap is only useful if it is legal.'}
  },
  strategies: {
    undercut:{explanation:'The undercut means stopping before a rival and using fresh tyres to set faster laps while the rival remains on older tyres.',tradeoff:'It can gain track position but may expose the driver to traffic, a slow warm-up lap or a Safety Car that arrives at the wrong time.',example:'If a driver is stuck behind a rival, the team may pit one lap earlier and hope the fresh-tyre pace creates enough time to emerge ahead after the rival stops.'},
    overcut:{explanation:'The overcut means staying out after a rival pits and using the extra laps to build a time advantage before making your own stop.',tradeoff:'It only works if the old tyres retain enough pace and the rival does not gain too much on fresh rubber.',example:'On a cool track where new tyres are difficult to warm up, staying out can sometimes be faster than stopping immediately.'},
    'go-long':{explanation:'Going long means extending a stint instead of responding immediately to a rival’s pit stop.',tradeoff:'The driver sacrifices immediate track position in exchange for fresher tyres later.',example:'A driver may stay out during a Safety Car threat or when overtaking is difficult, hoping a late stop gives them a strong final stint.'},
    'one-stop':{explanation:'A one-stop race plan uses one scheduled tyre change and therefore spends less time in the pit lane.',tradeoff:'The driver must make the tyres last, so the car may be slower at the end of a long stint.',example:'A durable compound can be used for a long middle stint while the driver protects it to avoid a second stop.'},
    'two-stop':{explanation:'A two-stop plan trades an additional pit-lane visit for more time on faster, fresher tyres.',tradeoff:'The extra stop costs track position and pit-lane time, but can recover more lap time through lower tyre degradation.',example:'If the tyres fall away quickly, two shorter stints can be faster overall than stretching one set too far.'},
    'safety-car':{explanation:'A Safety Car window is an opportunity to pit while the field is running slower, reducing the relative time cost of the stop.',tradeoff:'The team cannot control exactly when the Safety Car appears or how long it lasts.',example:'A driver with a tyre change due soon may gain a major strategic advantage if a Safety Car appears at exactly the right moment.'}
  },
  tyres: {
    hard:{explanation:'The hard slick is designed to offer long stint life and stable performance at the cost of lower peak grip compared with softer compounds.',conditions:'Useful when degradation is high, the track is hot or a team needs a long stint.',driverFeel:'The driver normally gets a more durable but less immediately responsive tyre compared with a soft compound.',example:'A hard tyre can be valuable for the middle or final stint when the team needs to reach the finish without another stop.',strategyNote:'Hard tyres can make a one-stop strategy easier, but their warm-up and peak pace must be considered.'},
    medium:{explanation:'The medium slick sits between the hard and soft in expected grip and life and is often the most flexible strategic option.',conditions:'Useful when a team wants a compromise between race pace and tyre life.',driverFeel:'It generally offers a predictable balance of grip and durability.',example:'A team may use the medium for a middle stint because it gives enough pace without the short life of the soft.',strategyNote:'The medium is often valuable because it leaves several strategy options open.'},
    soft:{explanation:'The soft slick provides the highest peak grip of the selected dry compounds but normally has shorter life.',conditions:'Useful for qualifying, short aggressive stints and situations where immediate lap time matters most.',driverFeel:'It can feel responsive and grippy when inside its operating window, but performance can fall away more quickly.',example:'A driver may use a new soft tyre for the final qualifying attempt to maximise one-lap performance.',strategyNote:'Soft tyres are not automatically the fastest race choice because degradation and pit-stop cost matter.'},
    intermediate:{explanation:'The intermediate is the green wet-weather tyre for conditions where slicks no longer provide enough grip but the track is not wet enough to require full wets.',conditions:'Useful in light or mixed rain and on a drying or damp circuit.',driverFeel:'It provides extra water displacement and more confidence than a slick in damp conditions.',example:'If rain starts during a race and the track becomes too wet for slicks, a team may switch to intermediates.',strategyNote:'The crossover point between slicks and intermediates is a major strategic decision because a tyre can quickly become too hot or too cold for the conditions.'},
    wet:{explanation:'The full wet is designed to move substantially more water than an intermediate in heavy rain and standing-water conditions.',conditions:'Used when water levels are too high for intermediates to work safely and effectively.',driverFeel:'The car gains greater water-displacement capability, although lap speed is lower in the heavy-rain conditions where it is needed.',example:'In a heavily flooded section of track, full wets can reduce aquaplaning risk compared with a less capable tyre.',strategyNote:'Visibility and standing water can still make conditions too dangerous for racing even when a wet-weather tyre is available.'}
  }
}
