const glossaryRows=getContent('glossary')
for (const row of glossaryRows) {
  const term=String(row.term||'')
  const extra={
    explanation:row.definition,
    raceUse:`${term} can appear in team radio, timing analysis, technical discussions or race commentary depending on the situation.`,
    example:`For a beginner, the easiest way to recognise ${term} is to connect it with the part of F1 it changes — car balance, grip, speed, energy, tyres, strategy or the rules.`,
    whyItMatters:`Knowing ${term} helps you understand why a driver, engineer or commentator describes a particular problem or decision.`,
    beginnerTip:'When you hear this term, ask what it changes on the car or in the race. That single question usually reveals its meaning.'
  }
  putContent('glossary',`${row.letter}-${row.term}`,{...row,...extra})
}
// Upgrade a set of high-value terms with concrete beginner examples.
const glossaryExamples={
  'Active aerodynamics':{explanation:'The 2026 car uses moveable aerodynamic elements at the front and rear. They can change between configurations that prioritise cornering load and straight-line efficiency.',example:'Think of it as the car changing its aerodynamic shape for different parts of a lap: more load in corners and less drag on suitable straights.',whyItMatters:'It is one of the most visible changes in the 2026 technical rules and replaces the old DRS concept.',beginnerTip:'Active aero is about changing the car’s aerodynamic balance while it is running, not simply adding a fixed wing.'},
  DRS:{explanation:'DRS was the Drag Reduction System used before 2026. It opened a rear-wing flap in specified conditions to reduce drag and help a following car attack.',example:'A driver close enough to a rival could use DRS on an eligible straight and gain extra speed.',whyItMatters:'DRS is important for understanding older races and the history behind the 2026 overtaking system.',beginnerTip:'In 2026, learn DRS as the previous system; the new rules use active aero and Overtake Mode.'},
  'Overtake Mode':{explanation:'Overtake Mode is a new-for-2026 energy deployment aid designed to help a following car attack. It replaces DRS as the main straight-line overtaking aid.',example:'A driver within the required gap at the detection point can use the additional electrical performance on the following lap.',whyItMatters:'It changes overtaking from a simple wing-opening action into an energy-management decision.',beginnerTip:'Remember: active aero manages aerodynamic drag and downforce; Overtake Mode manages electrical performance for an attack.'},
  'Lift and coast':{explanation:'The driver lifts off the throttle before the normal braking point and coasts for part of the approach to a corner.',example:'If an engineer says “lift and coast for three corners”, the driver deliberately gives up a little lap time to save fuel or recover energy.',whyItMatters:'It shows that F1 drivers are managing more than tyre grip — they also manage fuel and electrical energy.',beginnerTip:'Lift and coast = lift earlier, coast longer, save resources.'}
}
for (const row of getContent('glossary')) { const e=glossaryExamples[row.term]; if(e) putContent('glossary',`${row.letter}-${row.term}`,{...row,...e}) }


const HISTORY_EDU={
1950:{why:'The championship needed a common international framework so major Grand Prix competition could be recognised as one world title.',impact:'It created the sporting foundation from which the modern championship evolved.',example:'Nino Farina became the first Drivers’ World Champion.'},
1952:{why:'There were not enough suitable Formula 1 cars to maintain a viable championship grid.',impact:'Using Formula 2 regulations kept the championship running while the sport adapted.',example:'Smaller-engined cars competed for the World Championship in 1952 and 1953.'},
1958:{why:'The sport needed to recognise the manufacturers and teams whose cars competed as well as the individual drivers.',impact:'The Constructors’ Championship created a permanent team-level competition.',example:'Vanwall became the first Constructors’ World Champion.'},
1961:{why:'Engine performance and speeds were increasing, so the technical formula was reset.',impact:'The 1.5-litre formula changed the balance between engine power, chassis efficiency and reliability.',example:'Teams had to find performance without relying on large-displacement engines.'},
1966:{why:'The previous 1.5-litre formula had run its course and the sport wanted a new power ceiling.',impact:'The return to larger engines opened another major engine-development era.',example:'Naturally aspirated engines up to three litres became eligible.'},
1968:{why:'Teams discovered that airflow could generate performance without adding engine power.',impact:'Aerodynamic development became a central engineering discipline in F1.',example:'Wings began appearing in increasingly sophisticated forms on F1 cars.'},
1970:{why:'Teams were looking for more efficient ways to generate downforce.',impact:'Underbody airflow became a major area of experimentation and eventually led to full ground-effect cars.',example:'Lotus and other teams developed ideas that treated the floor as an aerodynamic device.'},
1978:{why:'Ground-effect tunnels could create large amounts of downforce with less drag than simply making the wings larger.',impact:'The technique transformed cornering performance but also created new safety and stability challenges.',example:'Lotus demonstrated the effectiveness of shaped sidepods and underbody tunnels.'},
1983:{why:'The FIA wanted to reduce the extreme aerodynamic loads and unpredictable behaviour associated with sliding-skirt ground-effect cars.',impact:'Flat-bottom rules changed how teams generated downforce and pushed development back toward wings and diffusers.',example:'Teams could no longer seal the floor to the track with sliding skirts.'},
1988:{why:'Turbo engines had become extremely powerful, and the rules were preparing for their removal.',impact:'The final turbo season became a technical transition point between turbocharged and naturally aspirated eras.',example:'Turbo restrictions limited boost and fuel use before the 1989 ban.'},
1989:{why:'The turbo formula had become too expensive and difficult to control.',impact:'Naturally aspirated engines became the sole engine architecture.',example:'Teams switched their focus to high-revving naturally aspirated designs.'},
1994:{why:'F1 wanted the driver to have more direct control rather than relying on electronic assistance.',impact:'Electronic driver aids were removed while safety requirements also became a major focus after the events at Imola.',example:'Active suspension, traction control and launch-control systems were prohibited at the start of the season.'},
1998:{why:'The FIA wanted to reduce cornering performance and change the mechanical-grip balance.',impact:'Grooved tyres and narrower cars altered how drivers generated grip and how teams designed their suspension and aerodynamics.',example:'Dry-weather tyres visibly gained grooves instead of using a fully slick surface.'},
2003:{why:'The sporting format was repeatedly adjusted to make qualifying and the points battle more engaging.',impact:'The single-lap qualifying format changed the risk-reward balance and the points expansion rewarded more finishers.',example:'More drivers could score championship points than under the earlier top-six system.'},
2009:{why:'F1 wanted to reduce aerodynamic complexity and introduce new energy-recovery technology.',impact:'KERS brought hybrid energy recovery into the sport while slick tyres and revised wings changed mechanical and aerodynamic balance.',example:'Drivers could deploy recovered braking energy for extra performance.'},
2011:{why:'Overtaking was difficult in disturbed air, so F1 introduced a controlled aerodynamic aid.',impact:'DRS became a defining part of race strategy for more than a decade.',example:'A driver within the required gap at a detection point could open the rear-wing flap in a DRS zone.'},
2014:{why:'F1 moved toward greater efficiency and a more sophisticated hybrid power system.',impact:'The 1.6-litre V6 turbo-hybrid era made energy recovery, fuel flow and thermal efficiency central to performance.',example:'The MGU-K recovered braking energy while the MGU-H recovered exhaust energy.'},
2017:{why:'F1 wanted cars that were faster and more visually aggressive.',impact:'Wider tyres and larger aerodynamic surfaces increased cornering speeds and changed tyre management.',example:'Cars became wider and carried larger tyres compared with the previous generation.'},
2019:{why:'F1 adjusted the front wing and other race-management elements to improve following and simplify some aerodynamic behaviour.',impact:'The front wing became a larger part of how teams managed the car’s airflow and balance.',example:'Teams had to redesign their aerodynamic philosophy around the new front-wing regulations.'},
2021:{why:'F1 introduced financial controls while also reducing some aerodynamic load to protect tyre performance and improve close racing.',impact:'The cost cap changed how teams planned development and spending.',example:'Teams had to make trade-offs about which upgrades were worth their limited development budget.'},
2022:{why:'The FIA wanted cars that could follow each other more closely by reducing the negative effect of turbulent air.',impact:'Ground-effect floors returned and the aerodynamic philosophy changed dramatically.',example:'Venturi-style tunnels under the floor generated much of the car’s downforce.'},
2026:{why:'F1 redesigned the cars around closer racing, greater electrical power, efficiency and a new aerodynamic philosophy.',impact:'Active front and rear aerodynamic elements, a new power-unit balance, sustainable fuel and new energy-management concepts reshape the cars.',example:'Active aero can switch between configurations that prioritise cornering load and straight-line efficiency, while Overtake Mode replaces the old DRS concept.'}
}
for(const row of getContent('history')){const e=HISTORY_EDU[Number(row.year)];if(e)putContent('history',row.id,{...row,...e})}

